# Solution for Lieges of Legendre game

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    k_odd = k % 2 == 1

    memo = {}

    def get_grundy(x):
        if x == 0:
            return 0
        if x in memo:
            return memo[x]

        # Option 1: Remove 1 cow, leads to state x-1
        reachable = {get_grundy(x - 1)}

        # Option 2: If x is even, split into k piles of x/2
        if x % 2 == 0:
            half = x // 2
            if k_odd:
                # k is odd: k copies of Grundy(half) XOR to Grundy(half)
                reachable.add(get_grundy(half))
            else:
                # k is even: k copies XOR to 0
                reachable.add(0)

        # Compute mex (minimum excluded value)
        result = 0
        while result in reachable:
            result += 1
        memo[x] = result
        return result

    # XOR all pile Grundy numbers
    xor_sum = 0
    for val in a:
        xor_sum ^= get_grundy(val)

    if xor_sum > 0:
        return "Kevin"
    else:
        return "Nicky"

