    line_idx += 1

    results = []

    for _ in range(t):
        # Skip line with empty line
        line_idx += 1
        if line_idx >= len(lines):
            break

        try:
            n = int(lines[line_idx])
        except:
            break
        line_idx += 1

        # Parse nodes
        nodes = []
        for i in range(n):
            try:
                parts = list(map(int, lines[line_idx].split()))
                line_idx += 1
                if parts[0] == -1:
                    nodes.append({
                        'type': 'internal',
                        'left': parts[1],
                        'right': parts[2]
                    })
                else:
                    nodes.append({
                        'type': 'leaf',
                        'value': parts[0]
                    })
            except (IndexError, ValueError):
                break

        # Helper to count leaves in subtree
        def count_leaves(u):
            if nodes[u]['type'] == 'leaf':
                return 1
            else:
                return count_leaves(nodes[u]['left']) + count_leaves(nodes[u]['right'])

        # Memoized recursive solver
        @lru_cache(maxsize=None)
        def dp(u):
            node = nodes[u]
            if node['type'] == 'leaf':
                return node['value']
            else:
                left = nodes[u]['left']
                right = nodes[u]['right']

                left_val = dp(left)
                right_val = dp(right)

                left_leaves = count_leaves(left)
                right_leaves = count_leaves(right)

                # Number of actual merges in the subtrees
                prev_moves = (left_leaves - 1) + (right_leaves - 1)

                # If even number of prior moves, it's Pieguy's turn to choose (maximize)
                # If odd, it's Piegirl's turn to choose (minimize)
                if prev_moves % 2 == 0:
                    return max(left_val, right_val)
                else:
                    return min(left_val, right_val)

        if nodes:
            results.append(dp(0))

    return '\n'.join(map(str, results))

