def factorial(n):
    res = 1
    for i in range(2, n+1):
        res = (res * i) % MOD
    return res

def inv_factorial(n):
    return pow(factorial(n), MOD - 2, MOD)

def combinations(n, r):
    if r < 0 or r > n:
        return 0
    num = factorial(n)
    den = (inv_factorial(r) * inv_factorial(n-r)) % MOD
    return (num * den) % MOD

