    lines = input_string.strip('\n').split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1]

    # If k > n, impossible to have k consecutive episodes
    if k > n:
        return 'NO\n'

    # Case 1: Exactly k unwatched needed (k >= 1)
    if k > 0:
        # Check if any existing consecutive N's exceeds k
        consec_n = 0
        exceeds_k = False
        for c in s:
            if c == 'N':
                consec_n += 1
                if consec_n > k:
                    exceeds_k = True
                    break
            else:
                consec_n = 0

        if exceeds_k:
            return 'NO\n'
        if consec_n > k:  # After reset, check final segment
            return 'NO\n'

        # Can we achieve exactly k? Check two conditions:
        # 1. We have at least one segment of N's with appropriate length
        # 2. OR there exists a ?-segment long enough to create k N's

        # Found existing segments of N's
        consec_q = 0
        for c in s:
            if c == '?':
                consec_q += 1
            else:
                if consec_q >= k:
                    return 'YES\n'
                consec_q = 0

        # Check final ? segment
        if consec_q >= k:
            return 'YES\n'

        # Check if existing N segments can help us reach k
        max_n = 0
        cur_n = 0
        for c in s:
            if c == 'N':
                cur_n += 1 else:
                max_n = max(max_n, cur_n)
                cur_n = 0
        max_n = max(max_n, cur_n)

        # If max_n >= k, can we exactly achieve k?
        # Yes if max_n == k or if we have ? to bridge
        if max_n >= k:
            return 'YES\n'

        return 'NO\n'

    # Case 2: k = 0, need no consecutive N's
    # This means no N characters at all
    for c in s:
        if c == 'N':
            return 'NO\n'

    return 'YES\n'

