def solution(input_string):
    lines = input_string.strip().split('\n')
    q = int(lines[0])
    results = []

    MOD = 10**9 + 7
    MAX_N = 1000005
    MAX_R = 1000005

    # Precompute smallest prime factor for fast factorization
    spf = list(range(MAX_N))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N, i):
                if spf[j] == j:
                    spf[j] = i

    def get_prime_factorization(n):
        factors = []
        while n > 1:
            p = spf[n]
            count = 0
            while n % p == 0:
                n //= p
                count += 1
            factors.append((p, count))
        return factors

    # Precompute f0(n) for all n
    f0 = [0] * MAX_N
    f0[1] = 1
    for i in range(2, MAX_N):
        factors = get_prime_factorization(i)
        distinct = len(factors)
        f0[i] = 1 << distinct

    # DP to compute f_r values
    # Process each query with memoization per query

    def compute_fr(r, n):
        if r == 0:
            return f0[n]

        # Recursive approach with memoization
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def cached_fr(r_val, val):
            if r_val == 0:
                return f0[val]
            if val == 1:
                return 1

            # Sum over p|val: f_{r-1}(p)
            total = 0
            for d in range(1, int(val**0.5) + 1):
                if val % d == 0:
                    total = (total + cached_fr(r_val - 1, d)) % MOD
                    if d * d != val:
                        total = (total + cached_fr(r_val - 1, val // d)) % MOD
            return total

        result = cached_fr(r, n)
        cached_fr.cache_clear()
        return result

    for i in range(1, q + 1):
        r, n = map(int, lines[i].split())
        result = compute_fr(r, n)
        results.append(str(result))

    return '\n'.join(results)


