    n = int(parts[0])
    m = int(parts[1])

    # Check for swap parameters (swapLR, swapUD)
    if len(parts) >= 4:
        swapLR = int(parts[2])
        swapUD = int(parts[3])
    elif len(parts) == 3:
        swapLR = int(parts[2])
        swapUD = 0
    elif len(parts) == 2:
        swapLR = 0
        swapUD = 0
    else:
        return ''

    # Parse grid
    grid_rows = []
    for i in range(n):
        row = lines[1 + i] if i + 1 < len(lines) else ''
        grid_rows.append(row)

    # Find finish cell F
    target = None
    for r in range(n):
        if 'F' in grid_rows[r]:
            target = (r, grid_rows[r].index('F'))
            break

    if target is None:
        return ''

    # BFS to find path from start (0, 0) to target
    from collections import deque
    start = (0, 0)
    queue = deque([(start, [])])
    visited = {start}

    def get_direction(dir_char):
        """Returns (dr, dc) for a direction character"""
        if dir_char == 'U':
            return (-1, 0)
        elif dir_char == 'D':
            return (1, 0)
        elif dir_char == 'L':
            return (0, -1)
        elif dir_char == 'R':
            return (0, 1)
        return (0, 0)

    def apply_swap(move_char, swapLR, swapUD):
        """Applies direction swaps to get actual output"""
        if swapLR and move_char in ['L', 'R']:
            return 'R' if move_char == 'L' else 'L'
        if swapUD and move_char in ['U', 'D']:
            return 'D' if move_char == 'U' else 'U'
        return move_char

    result = []

    while queue:
        (r, c), path = queue.popleft()

        if (r, c) == target:
            # Reverse path since we're going backwards
            result = path[::-1]
            break

        # Try all 4 directions
        for move_char in ['U', 'D', 'L', 'R']:
            dr, dc, actual_move = get_direction(move_char), None, None

            # Apply swaps to determine actual move direction
            if swapLR and move_char in ['L', 'R']:
                actual_move = 'R' if move_char == 'L' else 'L'
            elif swapUD and move_char in ['U', 'D']:
                actual_move = 'D' if move_char == 'U' else 'U'
            else:
                actual_move = move_char

            dr, dc = get_direction(actual_move)
            nr, nc = r + dr, c + dc

            # Check bounds (1-indexed positions, so 0 < row <= n, 0 < col <= m)
            if 0 < nr <= n and 0 < nc <= m:
                # Check for dangerous cell
                if grid_rows[nr-1][nc-1] == '*':
                    # Dangerous cell - jump to next (position unchanged means invalid, but we skip it)
                    continue
                elif grid_rows[nr-1][nc-1] == 'F':
                    continue  # Will be caught by check later

                new_pos = (nr - 1, nc - 1)  # Convert to 0-indexed for visited
                if new_pos not in visited:
                    visited.add(new_pos)
                    queue.append(((nr - 1, nc - 1), path + [actual_move]))

    # Apply swap conversion to get actual output
    actual_moves = []
    for move in result:
        actual_moves.append(apply_swap(move, swapLR, swapUD))

    return '\n'.join(actual_moves) + '\n'

