@lru_cache(maxsize=None)
def game_state(a, b, n):
    """
    Returns True if the current player wins from state (a,b), False otherwise.
    """
    # Calculate ways with exponentiation optimization
    def compute_ways(aa, bb):
        if aa > 10000 or bb > 60:  # Safety for overflow concerns
            try:
                return aa ** bb
            except:
                return float('inf')
        return aa ** bb

    ways = compute_ways(a, b)

    # Check if current state is terminal (already lost)
    if ways >= n:
        return False  # Current state is losing

    # Try both possible moves
    move1_win = game_state(a + 1, b, n)  # Add a box
    move2_win = game_state(a, b + 1, n)  # Add an item

    # If any move leads to opponent losing, current player wins
    if (move1_win and move2_win == False) or (move1_win == False and move2_win):
        # One move wins
        return True
    elif move1_win == False and move2_win == False:
        # Both moves lead to opponent winning -> current loses
        return False
    else:
        # At least one move is safe, opponent can't force immediate loss
        return True

