    def can_reach(time_limit):
        if time_limit == 0:
            cookies = 0

        cookies = 0
        # Active building configuration
        best_v, best_c = 1, 0  # Start with manual clicking

        # Use the order of building availability
        for t in range(time_limit):
            # Add cookies from active building
            cookies += best_v

            if cookies >= s:
                return True

            # Try to buy better buildings in cost order
            for v, c in sorted(buildings, key=lambda x: x[1]):
                if cookies >= c:
                    cookies -= c
                    best_v, best_c = v, c

        return cookies >= s

    # Binary search bounds
    low = 0
    high = max(s, 10 ** 16) + 10 ** 9
    ans = high

    while low <= high:
        mid = (low + high) // 2
